def _box_simplex(H, c, cap, budget):
    from scipy.optimize import minimize
    n = len(c)
    if budget == 0:
        return (np.zeros(n), float(c.min()))
    if budget == n * cap:
        w = np.full(n, cap)
        return (w, float((H @ w + c).max()))
    ones = np.ones(n)
    scale = max(np.linalg.norm(H, ord=np.inf), np.linalg.norm(c, ord=np.inf))
    if scale == 0:
        return (np.full(n, budget / n), 0.0)
    result = minimize(lambda w: ((0.5 * w @ H @ w + c @ w) / scale, (H @ w + c) / scale), np.full(n, budget / n), jac=True, method='SLSQP', bounds=[(0, cap)] * n, constraints=[{'type': 'eq', 'fun': lambda w: w.sum() - budget, 'jac': lambda w: ones}], options={'ftol': 1e-14, 'maxiter': 500})
    w = result.x
    tol = 1e-09 * cap
    (lo, hi) = (w <= tol, w >= cap - tol)
    free = ~(lo | hi)
    if np.any(free):
        polished = np.where(hi, cap, 0.0)
        count = int(free.sum())
        a = np.ones(count)
        kkt = np.block([[H[np.ix_(free, free)] / scale, -a[:, None]], [a[None, :], np.zeros((1, 1))]])
        rhs = np.r_[-(H @ polished + c)[free] / scale, budget - polished.sum()]
        solution = np.linalg.lstsq(kkt, rhs, rcond=None)[0]
        polished[free] = solution[:-1]
        nu = solution[-1] * scale
        reduced = H @ polished + c - nu
        if np.all((polished >= 0) & (polished <= cap)) and np.all(reduced[lo] >= -1e-11 * scale) and np.all(reduced[hi] <= 1e-11 * scale):
            return (polished, float(nu))
    g = H @ w + c
    if np.any(free):
        nu = np.mean(g[free])
    else:
        nu = 0.5 * (g[hi].max() + g[lo].min())
    return (w, float(nu))

def _rosette_design(ref, j):
    (own, nxt, prev) = (ref[:, j], ref[:, (j + 1) % 4], ref[:, (j - 1) % 4])
    return np.column_stack((np.ones(len(ref)), own, nxt, prev, own * nxt, own ** 3))
